import{_ as t,c as e,o as a,a3 as d}from"./chunks/framework.C5U8cnJv.js";const o="/xhh-blog/assets/image.DCHDd3mP.png",r="/xhh-blog/assets/image-18.OMZq3UU-.png",P=JSON.parse('{"title":"Qoder","description":"","frontmatter":{},"headers":[],"relativePath":"ai/qoder.md","filePath":"ai/qoder.md"}'),s={name:"ai/qoder.md"},c=d('<h1 id="qoder" tabindex="-1"><a href="https://qoder.com.cn/" target="_blank" rel="noreferrer">Qoder</a> <a class="header-anchor" href="#qoder" aria-label="Permalink to &quot;[Qoder](https://qoder.com.cn/)&quot;">​</a></h1><p>Qoder CN（原通义灵码）是阿里云 IDE AI 编程助手，原生适配 VSCode。支持仓库级代码理解、Agent 自动多文件修改、行间代码补全、代码审查，内置通义 Qwen 系列模型。</p><p>VSCode Qoder CN 插件：</p><p><img src="'+o+'" alt="alt text"></p><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h2><p>目录 <code>.lingma/skills/</code>，输入 <code>/技能名称</code> 调用</p><h2 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;MCP&quot;">​</a></h2><p>Qoder CN 聊天面板 =&gt; 右上角用户 =&gt; Settings =&gt; MCP Servers =&gt; Add by JSON:</p><p><img src="'+r+'" alt="alt text"></p><p>这里使用的是 MCP 协议的通用 STDIO 配置。</p><table tabindex="0"><thead><tr><th>对比</th><th>stdio</th><th>SSE/HTTP</th></tr></thead><tbody><tr><td>通信含义</td><td>本地进程管道通信，Qoder 拉起 Node 子进程，通过控制台输入输出传递MCP消息</td><td>HTTP SSE长流网络通信，先GET建立长连接，后续指令POST交互</td></tr><tr><td>Figma官方支持</td><td>❌ 官方无stdio版本，可使用第三方社区包<code>figma-mcp</code>、 <a href="https://github.com/GLips/Figma-Context-MCP" target="_blank" rel="noreferrer">figma-developer-mcp</a></td><td>✅ Figma官方MCP原生基于SSE</td></tr><tr><td>配置写法</td><td><code>command</code> + <code>args</code> + <code>env</code></td><td><code>type:http</code> + <code>url</code></td></tr></tbody></table>',11),i=[c];function l(n,h,p,m,_,g){return a(),e("div",null,i)}const b=t(s,[["render",l]]);export{P as __pageData,b as default};
